<script>
  const slides = [...document.querySelectorAll('.hero-slide')];
  const dots = [...document.querySelectorAll('.dot')];
  let current = 0;
  function showSlide(index) {
    current = (index + slides.length) % slides.length;
    slides.forEach((slide, i) => slide.classList.toggle('active', i === current));
    dots.forEach((dot, i) => dot.classList.toggle('selected', i === current));
  }
  document.getElementById('heroNext').addEventListener('click', () => showSlide(current + 1));
  document.getElementById('heroPrev').addEventListener('click', () => showSlide(current - 1));
  dots.forEach((dot, i) => dot.addEventListener('click', () => showSlide(i)));

  const row = document.getElementById('dealRow');
  let offset = 0;
  document.getElementById('dealNext').addEventListener('click', () => {
    offset = Math.min(offset + 280, row.scrollWidth - row.parentElement.clientWidth);
    row.style.transform = `translateX(-${offset}px)`;
  });
  document.getElementById('dealPrev').addEventListener('click', () => {
    offset = Math.max(0, offset - 280);
    row.style.transform = `translateX(-${offset}px)`;
  });
  document.querySelectorAll('.heart').forEach(button => button.addEventListener('click', () => {
    button.textContent = button.textContent === '♡' ? '♥' : '♡';
